		/** 
		 * Tests creating a new Transaction.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Transaction");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Transaction" );

			try {            
				Transaction entity = TransactionService.getTransactionInstance().createTransaction( generateNewEntity() );
				thePrimaryKey = entity.getTransactionId();
				LOGGER.info( "-- Successfully created a Transaction with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Transaction. 
		 */
		public Transaction testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Transaction" );

			Transaction entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Transaction with primary key" );
			msg.append( thePrimaryKey );
			
			TransactionFetchOneSummary fetchOneSummary = new TransactionFetchOneSummary( thePrimaryKey );

			try {
				entity = TransactionService.getTransactionInstance().getTransaction( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Transaction " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Transaction.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Transaction." );

			StringBuilder msg = new StringBuilder( "Failed to update a Transaction : " );        
			Transaction entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Transaction." );

				// for use later on...
				thePrimaryKey = entity.getTransactionId();

				TransactionService proxy = TransactionService.getTransactionInstance();            
				proxy.updateTransaction( entity );   

				LOGGER.info( "-- Successfully saved Transaction - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Transaction.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Transaction." );

			try{
			    Transaction entity = testRead(); 
				TransactionService.getTransactionInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Transaction with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Transaction with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Transactions.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Transactions:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Transaction : " );        
			List<Transaction> collection  = null;

			try {
				// call the static get method on the TransactionService
				collection = TransactionService.getTransactionInstance().getAllTransaction();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Transaction entity = null;            
					Iterator<Transaction> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getTransactionId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

